    if (!e) return false;
    if (e.kind === 'trigger') { g.placePlayer(e.x, e.y); g.lastExitTile = null; g.onStep(); }
    else { ok(adj(g, e), 'Hook chain: stand by ' + ch); ok(g.interact(), 'Hook chain: ' + ch + ' answers'); }
